<script setup>
import { reactive,ref,computed,onMounted,watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { workspace,loadStores } from '../../services/workspace.js';
import { auth,canFeature } from '../../services/auth.js';
import { notify,confirmDialog } from '../../services/notifications.js';
import { money } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
import DataTable from '../../components/DataTable.vue';

const route=useRoute(),router=useRouter(),origin=window.location.origin,loading=ref(true),saving=ref(false),error=ref(''),tab=ref(String(route.query.tab||'pagos'));
const store=ref(null);
const accountForm=reactive({id:'',name:'',accessToken:'',webhookSecret:'',sandbox:true,clearCredentials:false});
const paymentTypes={cash:'Efectivo',transfer:'Transferencia',mercadopago:'Mercado Pago'},deliveryTypes={pickup:'Retiro',shipping:'Envío',digital:'Digital',custom:'Personalizada'};
const paymentColumns=[{key:'name',label:'Forma de pago'},{key:'type',label:'Tipo'},{key:'deliveryIds',label:'Disponible para'},{key:'active',label:'Estado'}],deliveryColumns=[{key:'name',label:'Entrega'},{key:'type',label:'Tipo'},{key:'price',label:'Costo'},{key:'active',label:'Estado'}];
const visiblePayments=computed(()=>store.value?.payments||[]);
const mpAccounts=computed(()=>store.value?.integrations?.mercadopago?.accounts||[]);
const editingAccount=computed(()=>mpAccounts.value.find(account=>account.id===accountForm.id)||null);
const maxPayments=computed(()=>auth.user?.role==='admin'?0:Number(auth.entitlement?.maxPaymentMethods??0));
const maxDeliveries=computed(()=>auth.user?.role==='admin'?0:Number(auth.entitlement?.maxDeliveryMethods??0));
const canAddPayment=computed(()=>!maxPayments.value||(store.value?.payments?.length||0)<maxPayments.value);
const canAddDelivery=computed(()=>!maxDeliveries.value||(store.value?.deliveries?.length||0)<maxDeliveries.value);
function quotaText(current,limit){return limit?`${current} / ${limit}`:`${current} · sin límite del plan`}
function normalizeTab(value){if(value==='mercadopago'&&!canFeature('payments.mercadopago'))return 'pagos';return ['pagos','entregas','mercadopago'].includes(value)?value:'pagos'}
watch(tab,value=>{const safe=normalizeTab(value);if(safe!==value){tab.value=safe;return}router.replace({query:{tab:value}})});
onMounted(()=>{tab.value=normalizeTab(tab.value);load()});
async function load(){try{store.value=await api.get(`/stores/${workspace.activeStoreId}`);if(accountForm.id&&!mpAccounts.value.some(account=>account.id===accountForm.id))resetAccount();}catch(e){error.value=e.message}finally{loading.value=false}}
async function remove(kind,row){if(!await confirmDialog({title:kind==='payments'?'Quitar forma de pago':'Quitar forma de entrega',message:'Dejará de ofrecerse en nuevas compras. Los pedidos existentes conservarán su información. Podés desactivarla desde Editar si preferís conservar su configuración.',confirmText:'Quitar',danger:true}))return;saving.value=true;try{const latest=await api.get(`/stores/${workspace.activeStoreId}`);if(kind==='deliveries'&&latest.payments.some(p=>p.deliveryIds.includes(row.id)))throw new Error('Esta entrega está asociada a un medio de pago. Editá primero esa forma de pago para quitar la asociación.');const payload={payments:latest.payments,deliveries:latest.deliveries,expectedUpdatedAt:latest.updatedAt};payload[kind]=payload[kind].filter(x=>x.id!==row.id);await api.put(`/stores/${workspace.activeStoreId}/payments`,payload);notify.success('Opción eliminada.');await load();await loadStores()}catch(e){notify.error(e.message)}finally{saving.value=false}}
function resetAccount(){Object.assign(accountForm,{id:'',name:'',accessToken:'',webhookSecret:'',sandbox:true,clearCredentials:false})}
function editAccount(account){Object.assign(accountForm,{id:account.id,name:account.name,accessToken:'',webhookSecret:'',sandbox:account.sandbox===true,clearCredentials:false})}
function webhookUrl(id){return id?`${origin}/api/webhooks/mercadopago/${workspace.activeStoreId}/${encodeURIComponent(id)}`:''}
async function saveAccount(){saving.value=true;error.value='';try{const payload={name:accountForm.name.trim(),sandbox:accountForm.sandbox};if(accountForm.accessToken.trim())payload.accessToken=accountForm.accessToken.trim();if(accountForm.webhookSecret.trim())payload.webhookSecret=accountForm.webhookSecret.trim();if(accountForm.clearCredentials)payload.clearCredentials=true;let saved;if(accountForm.id)saved=await api.put(`/stores/${workspace.activeStoreId}/mercadopago/accounts/${encodeURIComponent(accountForm.id)}`,payload);else saved=await api.post(`/stores/${workspace.activeStoreId}/mercadopago/accounts`,payload);notify.success(accountForm.id?'Cuenta de Mercado Pago actualizada.':'Cuenta de Mercado Pago creada.');await load();const current=mpAccounts.value.find(account=>account.id===saved.id);if(current)editAccount(current);await loadStores()}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
async function removeAccount(account){if(!await confirmDialog({title:'Quitar cuenta de Mercado Pago',message:`Se quitará “${account.name}”. Solo puede eliminarse si nunca fue usada por una forma de pago ni por un pedido. Los pedidos históricos necesitan conservar su cuenta para futuras verificaciones.`,confirmText:'Quitar cuenta',danger:true}))return;saving.value=true;try{await api.delete(`/stores/${workspace.activeStoreId}/mercadopago/accounts/${encodeURIComponent(account.id)}`);if(accountForm.id===account.id)resetAccount();notify.success('Cuenta de Mercado Pago eliminada.');await load();await loadStores()}catch(e){notify.error(e.message)}finally{saving.value=false}}
function deliveryNames(ids){return ids.length?ids.map(id=>store.value.deliveries.find(d=>d.id===id)?.name||'Entrega no disponible').join(', '):'Todas las entregas'}
</script>

<template><div><header class="p-page-header"><div><p class="p-eyebrow">UNA COMPRA SIMPLE, DE PRINCIPIO A FIN</p><h1>Cobros y entregas</h1><p>Ofrecé opciones claras y decidí qué medios de pago están disponibles para cada entrega.</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><template v-else-if="store"><nav class="p-tabs" aria-label="Opciones de cobros y entrega"><button type="button" :class="{active:tab==='pagos'}" @click="tab='pagos'"><Icon name="credit" :size="16"/>Formas de pago</button><button type="button" :class="{active:tab==='entregas'}" @click="tab='entregas'"><Icon name="truck" :size="16"/>Formas de entrega</button><button v-if="canFeature('payments.mercadopago')" type="button" :class="{active:tab==='mercadopago'}" @click="tab='mercadopago'"><Icon name="shield" :size="16"/>Mercado Pago</button></nav>
<section v-if="tab==='pagos'"><div class="p-section-title"><div><h2>Formas de pago</h2><p>Podés activar varias y definir cuándo ofrecerlas.</p></div><RouterLink v-if="canAddPayment" to="/app/payments/methods/new" class="btn btn-primary"><Icon name="plus" :size="15"/>Agregar pago</RouterLink><button v-else class="btn btn-secondary" disabled>Límite alcanzado</button></div><div class="p-info quota-info"><strong>{{quotaText(store.payments.length,maxPayments)}} formas de pago configuradas.</strong><span v-if="maxPayments&&!canAddPayment"> Para agregar otra, quitá una existente o cambiá de plan.</span></div><DataTable :rows="visiblePayments" :columns="paymentColumns" :loading="saving" empty-text="Agregá tu primera forma de pago."><template #cell-name="{row}"><div class="p-product-cell"><span class="p-product-thumb"><Icon name="credit" :size="18"/></span><strong>{{row.name}}</strong></div></template><template #cell-type="{value}">{{paymentTypes[value]}}</template><template #cell-deliveryIds="{value}"><span class="p-break" style="display:block;max-width:280px">{{deliveryNames(value)}}</span></template><template #cell-active="{value}"><span class="p-badge dot" :class="value?'green':'orange'">{{value?'Habilitada':'Deshabilitada'}}</span></template><template #actions="{row}"><RouterLink :to="`/app/payments/methods/${row.id}`" class="p-icon-btn" title="Editar medio de pago"><Icon name="edit" :size="14"/></RouterLink><button class="p-icon-btn danger" title="Quitar medio de pago" @click="remove('payments',row)"><Icon name="trash" :size="14"/></button></template></DataTable><div class="p-info">Ejemplo: configurá Efectivo y seleccioná únicamente Retiro en el local. En el checkout solo se ofrecerá al elegir esa entrega.</div></section>
<section v-else-if="tab==='entregas'"><div class="p-section-title"><div><h2>Formas de entrega</h2><p>Costos e instrucciones para cada alternativa.</p></div><RouterLink v-if="canAddDelivery" to="/app/payments/deliveries/new" class="btn btn-primary"><Icon name="plus" :size="15"/>Agregar entrega</RouterLink><button v-else class="btn btn-secondary" disabled>Límite alcanzado</button></div><div class="p-info quota-info"><strong>{{quotaText(store.deliveries.length,maxDeliveries)}} formas de entrega configuradas.</strong><span v-if="maxDeliveries&&!canAddDelivery"> Para agregar otra, quitá una existente o cambiá de plan.</span></div><DataTable :rows="store.deliveries" :columns="deliveryColumns" :loading="saving" empty-text="Elegí cómo van a llegar tus productos."><template #cell-name="{row}"><div class="p-product-cell"><span class="p-product-thumb"><Icon name="truck" :size="18"/></span><strong>{{row.name}}</strong></div></template><template #cell-type="{value}">{{deliveryTypes[value]}}</template><template #cell-price="{value}"><strong>{{Number(value)===0?'Gratis':money(value)}}</strong></template><template #cell-active="{value}"><span class="p-badge dot" :class="value?'green':'orange'">{{value?'Habilitada':'Deshabilitada'}}</span></template><template #actions="{row}"><RouterLink :to="`/app/payments/deliveries/${row.id}`" class="p-icon-btn" title="Editar entrega"><Icon name="edit" :size="14"/></RouterLink><button class="p-icon-btn danger" title="Quitar entrega" @click="remove('deliveries',row)"><Icon name="trash" :size="14"/></button></template></DataTable></section>
<section v-else-if="tab==='mercadopago'&&canFeature('payments.mercadopago')"><div class="p-section-card"><div class="p-section-title"><div><h2>Mercado Pago · Checkout Pro</h2><p>Podés conectar varias cuentas y elegir cuál recibe el cobro en cada forma de pago Checkout Pro.</p></div><button type="button" class="btn btn-primary" @click="resetAccount"><Icon name="plus" :size="15"/>Nueva cuenta</button></div><div v-if="!mpAccounts.length" class="p-info">Creá una cuenta para comenzar. Después de guardarla vas a obtener su dirección exclusiva para recibir notificaciones.</div><div v-else class="mp-account-list"><article v-for="account in mpAccounts" :key="account.id" class="mp-account-row"><div><strong>{{account.name}}</strong><small>{{account.sandbox?'Modo de prueba':'Modo real'}}</small></div><span class="p-badge" :class="account.hasAccessToken&&account.hasWebhookSecret?'green':'orange'">{{account.hasAccessToken&&account.hasWebhookSecret?'Configurada':'Falta configurar'}}</span><div class="p-inline"><button type="button" class="p-icon-btn" title="Editar cuenta" @click="editAccount(account)"><Icon name="edit" :size="14"/></button><button type="button" class="p-icon-btn danger" title="Quitar cuenta" @click="removeAccount(account)"><Icon name="trash" :size="14"/></button></div></article></div></div>
<form class="p-form" @submit.prevent="saveAccount"><section class="p-section-card"><div class="p-section-title"><div><h2>{{accountForm.id?'Editar cuenta':'Nueva cuenta de Mercado Pago'}}</h2><p>Usá un nombre que te permita reconocer fácilmente qué cuenta recibirá los cobros.</p></div><span v-if="editingAccount" class="p-badge" :class="editingAccount.hasAccessToken&&editingAccount.hasWebhookSecret?'green':'orange'">{{editingAccount.hasAccessToken&&editingAccount.hasWebhookSecret?'Lista para usar':'Configuración pendiente'}}</span></div><div class="p-form-grid"><div class="p-field full"><label for="mp-account-name">Nombre de la cuenta *</label><input id="mp-account-name" v-model.trim="accountForm.name" required maxlength="120" placeholder="Ej. Mercado Pago principal"/></div><div v-if="accountForm.id" class="p-field full"><label>Dirección para recibir notificaciones</label><code class="mp-webhook-url">{{webhookUrl(accountForm.id)}}</code><small>Copiá esta dirección en la configuración de notificaciones de esta cuenta de Mercado Pago y activá las notificaciones de pagos.</small></div><div v-else class="p-field full"><div class="p-info">Primero guardá la cuenta. MiTiendaYa generará su dirección exclusiva para recibir notificaciones.</div></div><div class="p-field full"><label for="mp-token">Clave de acceso</label><input id="mp-token" v-model="accountForm.accessToken" type="password" autocomplete="new-password" :placeholder="editingAccount?.hasAccessToken?'Configurada · dejá vacío para conservarla':'APP_USR-... o TEST-...'"/><small>Se guarda de forma segura y no se vuelve a mostrar después de guardarla.</small></div><div class="p-field full"><label for="mp-secret">Clave de seguridad para notificaciones</label><input id="mp-secret" v-model="accountForm.webhookSecret" type="password" autocomplete="new-password" :placeholder="editingAccount?.hasWebhookSecret?'Configurada · dejá vacío para conservarla':'Clave secreta de la aplicación'"/></div><label class="p-check"><input v-model="accountForm.sandbox" type="checkbox"/>Modo de prueba</label><label v-if="editingAccount&&(editingAccount.hasAccessToken||editingAccount.hasWebhookSecret)" class="p-check"><input v-model="accountForm.clearCredentials" type="checkbox"/>Borrar credenciales al guardar</label></div><div v-if="accountForm.clearCredentials" class="p-info p-warning">La cuenta quedará sin credenciales y no podrá utilizarse en formas de pago activas hasta volver a configurarla.</div></section><footer class="p-form-footer"><small>Los campos de credenciales vacíos conservan los valores existentes.</small><div class="p-form-actions"><button v-if="accountForm.id" type="button" class="btn btn-secondary" @click="resetAccount">Cancelar edición</button><button class="btn btn-primary" :disabled="saving">{{saving?'Guardando...':accountForm.id?'Guardar cuenta':'Crear cuenta'}}</button></div></footer></form></section>
</template></div></template>

<style scoped>
.quota-info{margin-bottom:14px}.mp-account-list{display:grid;gap:10px}.mp-account-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:12px;align-items:center;padding:13px 14px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}.mp-account-row strong,.mp-account-row small{display:block}.mp-account-row small{color:var(--muted);margin-top:3px}.mp-webhook-url{display:block;width:100%;font-size:11px;line-height:1.55;background:var(--surface-alt);color:var(--text);border:1px solid var(--line);padding:12px;border-radius:6px;overflow-wrap:anywhere;white-space:normal}:global([data-theme="dark"]) .mp-webhook-url{background:var(--surface-strong);color:var(--text);border-color:var(--line-strong)}@media(max-width:700px){.mp-account-row{grid-template-columns:minmax(0,1fr) auto}.mp-account-row>.p-inline{grid-column:1/-1}}
</style>
